# sesslint completion (bash) - generated at runtime; do not edit.
_sesslint_complete() {
    local cur prev cmd opts
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"
    cmd=""
    for w in "${COMP_WORDS[@]:1}"; do
        case "$w" in
            -*) continue ;;
            *) cmd="$w"; break ;;
        esac
    done
    if [ -z "$cmd" ]; then
        COMPREPLY=( $(compgen -W "aaa-alias aah alpha bee beta" -- "$cur") )
        return 0
    fi
    case "$cmd" in
            alpha|aaa-alias|aah)
                opts="--alpha --zeta -z --quiet -q"
                case "$prev" in
                    --alpha) COMPREPLY=( $(compgen -W "aaa mid zzz" -- "$cur") ); return 0 ;;
                    --zeta) COMPREPLY=( $(compgen -W "aaa mid zzz" -- "$cur") ); return 0 ;;
                    -z) COMPREPLY=( $(compgen -W "aaa mid zzz" -- "$cur") ); return 0 ;;
                esac ;;
            beta|bee)
                opts="--quiet -q" ;;
        *) return 0 ;;
    esac
    COMPREPLY=( $(compgen -W "$opts" -- "$cur") )
    return 0
}
